mapper.select:
select a.id, a.operator_id, a.warehouse_id, a.classes_type, a.start_time, a.end_time, a.status, a.remark, a.create_by, a.create_time,
su.user_name
from t_classes a
left join sys_user su on a.operator_id = su.user_id

    inner join sys_user u on u.user_name = a.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    a.del_flag = '0'
    and a.operator_id = #{operatorId}
    and a.warehouse_id = #{warehouseId}
    and a.classes_type = #{classesType}
    and a.start_time = #{startTime}
    and a.end_time = #{endTime}
    and a.status = #{status}


${params.dataScope}
order by a.create_time desc

select count(*)
from t_classes a

    a.del_flag = '0'
    and a.id <> #{id}
    and a.operator_id = #{operatorId}
    and a.start_time <= #{startTime}
    and a.end_time >= #{endTime}
